#[path = "../src/crdt_engine/import_vault_ops.rs"]
mod import_vault_ops;

use import_vault_ops::{
    archive_import_source, archive_title_lookup_keys, build_vault_import_plan,
    create_import_result, fnv1a_path, import_result_envelope, parse_archive_import,
    resolve_archive_title, unresolved_links_warning, ArchiveImportParseResult, ArchiveImportSource,
};
use serde_json::{json, Value};
use std::collections::HashMap;
use std::path::PathBuf;

// ---------------------------------------------------------------------------
// Fixture helpers
// ---------------------------------------------------------------------------

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/vault_import")
}

fn fixture_bytes(name: &str) -> Vec<u8> {
    let path = fixture_dir().join(name);
    std::fs::read(&path).unwrap_or_else(|error| {
        panic!(
            "read {} failed ({error}); regenerate with `pnpm exec vitest run --config scripts/vitest.fixture.config.ts scripts/generate-vault-fixtures.test.mts` from frontend/",
            path.display()
        )
    })
}

fn fixture_json(name: &str) -> Value {
    serde_json::from_slice(&fixture_bytes(name)).expect("fixture JSON parses")
}

fn source_for(name: &str) -> ArchiveImportSource {
    archive_import_source(Some(&json!(name))).expect("known source")
}

/// Serialize the Rust parse result in the generator's normalized shape.
fn parse_result_json(result: &ArchiveImportParseResult) -> Value {
    json!({
        "documents": result
            .documents
            .iter()
            .map(|document| {
                json!({
                    "title": document.title,
                    "markdown": document.markdown,
                    "folderPath": document.folder_path,
                    "sourceFilename": document.source_filename,
                })
            })
            .collect::<Vec<_>>(),
        "wikilinks": result
            .wikilinks
            .iter()
            .map(|link| {
                json!({
                    "sourceTitle": link.source_title,
                    "targetTitle": link.target_title,
                    "displayText": link.display_text,
                    "sourceContext": link.source_context,
                    "isTag": link.is_tag,
                })
            })
            .collect::<Vec<_>>(),
        "warnings": result.warnings,
    })
}

fn parsed_fixture(name: &str) -> ArchiveImportParseResult {
    // Fixture names are `<source>` or `<source>-edge`.
    let base = name.split('-').next().expect("fixture name");
    let zip = fixture_bytes(&format!("{name}.zip"));
    parse_archive_import(source_for(base), &zip)
}

/// Compare the Rust parse of `<source>.zip` against the TS-generated
/// `<source>.parsed.json`, byte-exact field by field.
fn assert_parse_parity(source: &str) {
    let actual = parse_result_json(&parsed_fixture(source));
    let expected = fixture_json(&format!("{source}.parsed.json"));
    assert_eq!(
        actual, expected,
        "{source}: Rust parse result must match the frontend parser output"
    );
}

struct PlanCounts {
    documents_created: usize,
    folders_created: usize,
    wires_created: usize,
    tags_created: usize,
    unresolved_links: usize,
}

fn plan_counts(source: &str) -> PlanCounts {
    let parsed = parsed_fixture(source);
    let expected = fixture_json(&format!("{source}.expected.json"));
    let folder_name = expected["folderName"].as_str().expect("folderName");
    let plan = build_vault_import_plan(
        &parsed,
        Some(folder_name),
        "op-vault-fixture",
        1_760_000_000_000.0,
    )
    .expect("plan builds");
    let counts = PlanCounts {
        documents_created: plan.assignments.len(),
        folders_created: plan.folders.len(),
        wires_created: plan.wires.len(),
        tags_created: plan.tags_created,
        unresolved_links: plan.unresolved.len(),
    };
    assert_eq!(
        counts.documents_created,
        expected["documentsCreated"].as_u64().unwrap() as usize,
        "{source}: documentsCreated"
    );
    assert_eq!(
        counts.folders_created,
        expected["foldersCreated"].as_u64().unwrap() as usize,
        "{source}: foldersCreated"
    );
    assert_eq!(
        counts.wires_created,
        expected["wiresCreated"].as_u64().unwrap() as usize,
        "{source}: wiresCreated"
    );
    assert_eq!(
        counts.tags_created,
        expected["tagsCreated"].as_u64().unwrap() as usize,
        "{source}: tagsCreated"
    );
    assert_eq!(
        counts.unresolved_links,
        expected["unresolvedLinks"].as_u64().unwrap() as usize,
        "{source}: unresolvedLinks"
    );
    counts
}

// ---------------------------------------------------------------------------
// Parser parity against the TS-generated fixtures
// ---------------------------------------------------------------------------

#[test]
fn obsidian_parse_matches_frontend_parser() {
    assert_parse_parity("obsidian");
}

#[test]
fn notion_parse_matches_frontend_parser() {
    assert_parse_parity("notion");
}

#[test]
fn roam_parse_matches_frontend_parser() {
    assert_parse_parity("roam");
}

#[test]
fn edge_fixtures_parse_and_plan_match_frontend() {
    // Edge archives pin the subtler semantics: quoted frontmatter titles,
    // block-style `tags:` lists (greedy \s* captures '- alpha'), code-span
    // masking vs. unmasked hashtag replacement, image embeds, empty display
    // text, Notion percent-decoding (incl. malformed), CSV quoting/pipes,
    // Roam TODO/DONE + block refs (consumed before embeds), nested
    // wikilinks, attribute lines, V8 date rollover (Feb 30 → March), and the
    // multiple-JSON-files warning.
    for name in ["obsidian-edge", "notion-edge", "roam-edge"] {
        assert_parse_parity(name);
        plan_counts(name);
    }
}

#[test]
fn invalid_zip_yields_the_verbatim_warning() {
    for source in ["obsidian", "notion", "roam"] {
        let result = parse_archive_import(source_for(source), b"not zip");
        assert!(result.documents.is_empty());
        assert!(result.wikilinks.is_empty());
        assert_eq!(result.warnings, vec!["Invalid ZIP file".to_string()]);
    }
}

#[test]
fn empty_zip_reports_no_markdown_files() {
    // A structurally valid zip with no entries (EOCD record only).
    let mut empty = vec![0x50, 0x4b, 0x05, 0x06];
    empty.extend_from_slice(&[0u8; 18]);
    let result = parse_archive_import(ArchiveImportSource::Obsidian, &empty);
    assert_eq!(
        result.warnings,
        vec!["No markdown files found in ZIP".to_string()]
    );
    let result = parse_archive_import(ArchiveImportSource::Roam, &empty);
    assert_eq!(
        result.warnings,
        vec!["No JSON file found in ZIP".to_string()]
    );
}

